function renderWeeks(root,sel,fn){const host=$(root);if(!host)return;const chosen=getGwArray(sel),all=chosen.length===GWS.length&&GWS.every(g=>sel.has(g)),last3=GWS.slice(-3),last5=GWS.slice(-5),same=a=>a.length===chosen.length&&a.every((g,i)=>g===chosen[i]);const from=chosen[0]??GWS[0],to=chosen.at(-1)??GWS.at(-1);host.innerHTML=`<div class="gw-picker"><div class="gw-presets"><button data-gw-preset="all" class="${all?'selected':''}">All</button><button data-gw-preset="last3" class="${same(last3)?'selected':''}">Last 3</button><button data-gw-preset="last5" class="${same(last5)?'selected':''}">Last 5</button><span class="gw-summary">${chosen.length} GW${chosen.length===1?'':'s'}</span></div><div class="gw-range-row"><label>From<select data-gw-range="from">${GWS.map(g=>`<option value="${g}" ${g===from?'selected':''}>GW ${g}</option>`).join('')}</select></label><span>→</span><label>To<select data-gw-range="to">${GWS.map(g=>`<option value="${g}" ${g===to?'selected':''}>GW ${g}</option>`).join('')}</select></label><details class="gw-custom"><summary>Custom</summary><div class="gw-chip-grid">${GWS.map(g=>`<button data-gw="${g}" class="${sel.has(g)?'selected':''}" aria-pressed="${sel.has(g)}">${String(g).padStart(2,'0')}</button>`).join('')}</div></details></div></div>`;const apply=(arr)=>{sel.clear();arr.forEach(g=>sel.add(+g));cache.clear();fn();};$$('[data-gw-preset]',host).forEach(b=>b.onclick=()=>{const k=b.dataset.gwPreset;apply(k==='all'?GWS:k==='last3'?last3:last5);});$$('[data-gw-range]',host).forEach(x=>x.onchange=()=>{let a=+host.querySelector('[data-gw-range="from"]').value,b=+host.querySelector('[data-gw-range="to"]').value;if(a>b)[a,b]=[b,a];apply(GWS.filter(g=>g>=a&&g<=b));});$$('[data-gw]',host).forEach(b=>b.onclick=()=>{const g=+b.dataset.gw;if(sel.has(g)){if(sel.size>1)sel.delete(g);}else sel.add(g);cache.clear();fn();});}
function renderHome(){const formGw=Math.min(Math.max(...GWS),Number(state.gw)||Math.max(...GWS));const leaders=D.players.slice().sort((a,b)=>(val('f:form',b.id,new Set([formGw]))??-1)-(val('f:form',a.id,new Set([formGw]))??-1)).slice(0,6);$('#formLeaders').innerHTML=leaders.map((p,i)=>`<button class="leader-row" data-id="${p.id}"><span class="leader-rank">${String(i+1).padStart(2,'0')}</span>${pic(p)}<span class="leader-data"><strong>${esc(p.name)}</strong><small>${esc(tsh(playerTeamAtGw(p.id,formGw)||p.team))} · ${esc(p.position)}</small></span><span class="leader-value">${fmt(val('f:form',p.id,new Set([formGw])),1)} <small>form</small></span></button>`).join('');$$('#formLeaders [data-id]').forEach(b=>b.onclick=()=>openProfile(b.dataset.id));const weeks=SCHEDULE_GWS.length?SCHEDULE_GWS:GWS;if(!weeks.includes(Number(state.gw)))state.gw=firstUpcomingGw();$('#homeGw').innerHTML=weeks.map(g=>`<option value="${g}">GW ${String(g).padStart(2,'0')}</option>`).join('');$('#homeGw').value=state.gw;renderHomeGw();}
function renderHomeGw(){const schedule=(D.schedule||[]).filter(f=>Number(f.gw)===Number(state.gw)),indexed=new Map((D.fixtures||[]).map(f=>[String(f.id),f]));const games=(schedule.length?schedule:(D.fixtures||[]).filter(f=>Number(f.gw)===Number(state.gw))).slice().sort((a,b)=>{const ad=+new Date(a.date||0),bd=+new Date(b.date||0);return (Number.isFinite(ad)?ad:Infinity)-(Number.isFinite(bd)?bd:Infinity)||String(a.id).localeCompare(String(b.id));});const dateFmt=d=>{const x=new Date(d);return Number.isNaN(+x)?'Kick-off TBC':x.toLocaleString('en-GB',{weekday:'short',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});};$('#fixturesList').innerHTML=games.map(f=>{const done=indexed.get(String(f.id))||f,played=done?.homeScore!=null&&done?.awayScore!=null;return `<div class="fixture"><div class="fixture-club">${teamIcon(f.home)}<span>${esc(tn(f.home))}</span></div><div class="fixture-centre">${played?`<strong class="fixture-score">${done.homeScore} : ${done.awayScore}</strong><small>Full time</small>`:`<strong class="fixture-time">${esc(dateFmt(f.date))}</strong><small>${new Date(f.date)<new Date()?'Awaiting data update':'Scheduled'}</small>`}</div><div class="fixture-club away"><span>${esc(tn(f.away))}</span>${teamIcon(f.away)}</div></div>`;}).join('')||'<p class="data-foot">No fixtures found for this gameweek.</p>';const dates=games.map(f=>new Date(f.date)).filter(d=>!Number.isNaN(+d)).sort((a,b)=>a-b);if($('#homeGwMeta'))$('#homeGwMeta').textContent=dates.length?`GW ${String(state.gw).padStart(2,'0')} · ${dates[0].toLocaleDateString('en-GB',{day:'numeric',month:'short'})}${dates.length>1?' – '+dates.at(-1).toLocaleDateString('en-GB',{day:'numeric',month:'short'}):''}`:`GW ${String(state.gw).padStart(2,'0')}`;let map=new Map(D.teams.map(t=>[t.id,{...t,p:0,w:0,d:0,l:0,gf:0,ga:0,pts:0}]));for(const f of D.fixtures){if(+f.gw>state.gw||f.homeScore==null||f.awayScore==null)continue;const h=map.get(String(f.home)),a=map.get(String(f.away));if(!h||!a)continue;const hg=Number(f.homeScore),ag=Number(f.awayScore);h.p++;a.p++;h.gf+=hg;h.ga+=ag;a.gf+=ag;a.ga+=hg;if(hg>ag){h.w++;h.pts+=3;a.l++;}else if(hg<ag){a.w++;a.pts+=3;h.l++;}else{h.d++;a.d++;h.pts++;a.pts++;}}const rows=[...map.values()].sort((a,b)=>b.pts-a.pts||(b.gf-b.ga)-(a.gf-a.ga)||b.gf-a.gf||a.name.localeCompare(b.name));$('#standingsBody').innerHTML=rows.map((t,i)=>`<tr><td><b>${i+1}</b></td><td><div class="club-cell">${teamIcon(t.id)}<strong>${esc(t.name)}</strong></div></td><td>${t.p}</td><td>${t.w}</td><td>${t.d}</td><td>${t.l}</td><td>${t.gf}</td><td>${t.ga}</td><td>${t.gf-t.ga>0?'+':''}${t.gf-t.ga}</td><td><b>${t.pts}</b></td></tr>`).join('');}
$('#homeGw').onchange=e=>{state.gw=+e.target.value;renderHomeGw();scheduleAnalysisAutosave();};
