const median=arr=>{const s=arr.slice().sort((a,b)=>a-b);if(!s.length)return 0;const k=Math.floor(s.length/2);return s.length%2?s[k]:(s[k-1]+s[k])/2;};
function drawScatter(){const svg=$('#playerScatter');const pool=playerSub();const data=pool.map(p=>({p,team:playerTeamForWeeks(p.id,state.pGws),x:pVal(state.plotX,p.id),y:pVal(state.plotY,p.id)})).filter(d=>Number.isFinite(d.x)&&Number.isFinite(d.y));const subCount=pool.length;$('#scatterCount').textContent=`${data.length} / ${subCount} players`;const w=800,h=400,l=65,r=27,t=26,b=55;const xs=data.map(d=>d.x),ys=data.map(d=>d.y),extent=a=>{if(!a.length)return [0,1];let lo=Math.min(...a),hi=Math.max(...a);const pad=Math.max(.001,(hi-lo||Math.max(1,Math.abs(hi)))*.08);return [lo-pad,hi+pad];};const [minx,maxx]=extent(xs),[miny,maxy]=extent(ys);const dx=Math.max(.001,maxx-minx)/state.zoom,dy=Math.max(.001,maxy-miny)/state.zoom;const X=x=>l+(x-minx)/dx*(w-l-r),Y=y=>h-b-(y-miny)/dy*(h-t-b);const grid=Array.from({length:5},(_,i)=>{const x=l+i*(w-l-r)/4,y=t+i*(h-t-b)/4;return `<path d="M${x} ${t}V${h-b}M${l} ${y}H${w-r}" stroke="var(--border)" stroke-width="1" stroke-dasharray="3 5"/>`;}).join('');let html=`<rect width="800" height="400" fill="transparent"/>${grid}<path d="M${l} ${t}V${h-b}H${w-r}" fill="none" stroke="var(--muted)" opacity=".5"/><text x="400" y="388" class="axis-label" text-anchor="middle">${esc(ms(state.plotX))}</text><text x="17" y="195" class="axis-label" transform="rotate(-90 17 195)" text-anchor="middle">${esc(ms(state.plotY))}</text>`;
if(data.length&&state.quadrants!=='off'){const fn=state.quadrants==='median'?median:a=>a.reduce((q,v)=>q+v,0)/a.length;const cx=X(fn(xs)),cy=Y(fn(ys));html+=`<line x1="${Math.min(w-r,Math.max(l,cx))}" y1="${t}" x2="${Math.min(w-r,Math.max(l,cx))}" y2="${h-b}" stroke="var(--accent)" stroke-dasharray="5 5" opacity=".65"/><line x1="${l}" y1="${Math.min(h-b,Math.max(t,cy))}" x2="${w-r}" y2="${Math.min(h-b,Math.max(t,cy))}" stroke="var(--accent)" stroke-dasharray="5 5" opacity=".65"/>`;}
const searched=state.playerSearch.toLowerCase();let shown=0;for(const d of data){const x=X(d.x),y=Y(d.y);if(x<l||x>w-r||y<t||y>h-b)continue;shown++;const isHighlight=!!searched&&d.p.name.toLowerCase().includes(searched);const dim=(searched&&!isHighlight)||(state.lassoIds&&!state.lassoIds.has(String(d.p.id)));let c=state.markColor==='club'?tc(d.team):state.markColor==='position'?positions[d.p.position]:'#c3c7bd';const opacity=dim?.18:1;let mark;if(state.mark==='shirt')mark=`<path d="M-5 -7L-12 -3L-9 4L-6 2V10H6V2L9 4L12 -3L5 -7L2 -4H-2Z" fill="${c}" stroke="var(--bg)" stroke-width="1"/>`;else if(state.mark==='crest')mark=`<circle r="11" fill="${c}" stroke="var(--bg)" stroke-width="1.3"/><text x="0" y="3" fill="#0a1714" font-size="6" text-anchor="middle" font-weight="900">${esc(tsh(d.team))}</text><image href="${esc(logoUrl(d.team))}" x="-11" y="-11" width="22" height="22" preserveAspectRatio="xMidYMid meet"/>`;else if(state.mark==='photo')mark=`<circle r="12" fill="${c}" stroke="var(--bg)" stroke-width="1.2"/><image href="assets/players/${encodeURIComponent(d.p.code||'missing')}.webp" x="-12" y="-14" width="24" height="27" preserveAspectRatio="xMidYMid meet"/>`;else mark=`<circle r="${isHighlight?8:4.3}" fill="${c}" stroke="var(--bg)" stroke-width=".8"/>`;html+=`<g class="scatter-point" data-id="${d.p.id}" transform="translate(${x.toFixed(1)} ${y.toFixed(1)})" opacity="${opacity}" tabindex="0"><title>${esc(d.p.name)} · ${esc(ms(state.plotX))}: ${fmt(d.x,2)} · ${esc(ms(state.plotY))}: ${fmt(d.y,2)}</title>${mark}${isHighlight?'<circle r="14" fill="none" stroke="var(--accent)" stroke-width="2"/>':''}</g>`;}
svg.innerHTML=html;$('#chartInfo').textContent=`${shown} rendered · ${data.length} with both values · ${subCount-data.length} missing selected metrics · ${getGwArray(state.pGws).map(g=>'GW'+g).join(', ')}. Drag inside chart to lasso-select points.`;$$('#playerScatter .scatter-point').forEach(g=>{g.onclick=e=>{e.stopPropagation();openProfile(g.dataset.id);};g.onkeydown=e=>{if(e.key==='Enter')openProfile(g.dataset.id);};});state.plotData=data.map(d=>({...d,sx:X(d.x),sy:Y(d.y)}));}
