function renderComparePeriods(events){const root=$('#comparePeriods');if(!root)return;const halves=[events.filter(e=>e[12]===1),events.filter(e=>e[12]===2)];const cats=['pass','cross','shot','recovery','interception','tackle'];root.innerHTML=`<div class="period-compare"><div><b>First half</b><strong>${fmt(halves[0].length,0)}</strong></div><div><b>Second half</b><strong>${fmt(halves[1].length,0)}</strong></div></div>${cats.map(k=>`<div class="period-row"><span>${k}</span><b>${halves[0].filter(e=>e[2]===k).length}</b><b>${halves[1].filter(e=>e[2]===k).length}</b></div>`).join('')}`;}
