 touch:{key:'touch',label:'Bad touches',short:'Bad touches',event:e=>e[2]==='bad_touch',zone:e=>eventZone(e)},
 cross:{key:'cross',label:'Crosses',short:'Crosses',event:e=>e[2]==='cross',zone:e=>eventZone(e)},
 header:{key:'header',label:'Headers',short:'Headers',event:e=>e[2]==='shot'&&Array.isArray(e[13])&&e[13].includes('15'),zone:e=>eventZone(e)},
 pass:{key:'pass',label:'Final-third passes',short:'Final ⅓ passes',event:e=>e[2]==='pass'&&e[8]===1&&Number.isFinite(e[5])&&e[5]>=66.7&&Number.isFinite(e[6]),zone:e=>{const y=state.flipWidth?100-e[6]:e[6];return y<100/3?'right':y<200/3?'center':'left';}}
