const matchupMetricOrder=['shot','touch','cross','header','pass'];
const matrixCache=new Map(),lanePlayerCache=new Map(),eventNameToPlayer=new Map();
function activeMatchupKinds(){const arr=matchupMetricOrder.filter(k=>state.matchupEvents.has(k));return arr.length?arr:['shot'];}
function activeMatrixFields(){return activeMatchupKinds().flatMap(kind=>{const d=matchupMetricDefs[kind];return ['all','left','center','right'].map(zone=>({id:`${kind}_${zone==='all'?'total':zone}`,name:`${d.label} · ${zone==='all'?'total':zone==='center'?'Centre':zone[0].toUpperCase()+zone.slice(1)}`,kind,zone,label:d.label}));});}
function matchupEventKinds(e){return activeMatchupKinds().filter(k=>matchupMetricDefs[k].event(e));}
