if($('#matchupXIShapeStatus'))$('#matchupXIShapeStatus').innerHTML=['Goalkeeper','Defender','Midfielder','Forward'].map(role=>`<span class="${auto.counts[role]===shape[role]?'ok':auto.counts[role]>shape[role]?'over':'under'}">${xiRoleLabel(role)} ${auto.counts[role]}/${shape[role]}</span>`).join('');
$('#matchupXIStatus').textContent=state.xiStatus||(count?'Formation is automatic · player positions are fixed to FPL roles.':'Add players from matchup lanes. The formation will adapt automatically as the XI takes shape.');
