function matchupDirection(def,att){const totals=matrixNumbers(),conceded=totals.conceded.get(String(def));const zoneNames={left:'Left flank',center:'Centre',right:'Right flank'};return `<article class="pane matchup-direction"><div class="pane-head"><div><div class="section-kicker">DEFENSIVE WEAKNESS → OPPOSITION ACTIVITY</div><h3>${teamIcon(def)} ${esc(tn(def))} <span class="muted">vs</span> ${teamIcon(att)} ${esc(tn(att))}</h3></div></div><div class="lane-tiles">${['left','center','right'].map(z=>{const attackLane=z==='left'?'right':z==='right'?'left':'center',attacking=laneTargetingPlayers(att,attackLane),total=attacking.reduce((s,p)=>s+p.n,0);return `<section class="lane-tile ${state.matchupFocusZone===z?'focused':''}"><div class="lane-title"><strong>${zoneNames[z]}</strong><span>${esc(matchupLaneSummary(conceded,z))}</span></div><div class="lane-desc">${esc(tn(att))} attacking ${zoneNames[attackLane].toLowerCase()} · ${fmt(total,0)} unique selected event rows</div>${attacking.length?`${attacking.slice(0,8).map(person=>playerLaneRow(person,def,att,attackLane)).join('')}${attacking.length>8?`<details class="lane-more"><summary>View remaining ${attacking.length-8} players</summary>${attacking.slice(8).map(person=>playerLaneRow(person,def,att,attackLane)).join('')}</details>`:''}`:'<p class="data-foot">No reliably attributed player actions for the selected event types in this lane.</p>'}</section>`;}).join('')}</div><p class="data-foot">Player activity uses the selected event families above. “Headers” means shots recorded with the header body-part qualifier; aerial duels are not treated as headers. Final-third passes are successful passes ending in the attacking third. A header shot is one event row even when both Shots and Headers are selected, so the activity total does not double-count it.</p></article>`;}
