function isHeaderShot(e){return e?.[2]==='shot'&&Array.isArray(e[13])&&e[13].includes('15');}
function isShotOnTarget(e){return e?.[2]==='shot'&&(e[14]===16||(e[14]===15&&!(Array.isArray(e[13])&&e[13].includes('82'))));}
function crossHeaderTeamStats(teamId){const team=String(teamId),events=(eventsByTeam.get(team)||[]).filter(e=>state.boardGws.has(+e[0]));const crosses=events.filter(e=>e[2]==='cross'),headers=events.filter(isHeaderShot),allShots=events.filter(e=>e[2]==='shot');const playerCount=(rows,filterFn)=>{const m=new Map();for(const e of rows){if(filterFn&&!filterFn(e))continue;const id=String(e[15]||''),key=id||`name:${e[9]||'Unknown'}`,name=id?pName(id):(e[9]||'Unknown');if(!m.has(key))m.set(key,{id,name,n:0});m.get(key).n++;}return [...m.values()].sort((a,b)=>b.n-a.n||a.name.localeCompare(b.name));};const laneCounts={left:0,center:0,right:0};for(const e of crosses){const z=eventZone(e);if(laneCounts[z]!==undefined)laneCounts[z]++;}return {team,crosses:crosses.length,completed:crosses.filter(e=>e[8]===1).length,headers:headers.length,headerOnTarget:headers.filter(isShotOnTarget).length,headerGoals:headers.filter(e=>e[14]===16).length,allShots:allShots.length,laneCounts,topCrossers:playerCount(crosses),topHeaders:playerCount(headers)};}
