// CHART STUDIO — Phase 2: chart semantics are explicit and source-aware.
const chartTypes=[['scatter','Scatter'],['bubble','Bubble'],['bar','Bar / ranking'],['line','Line / GW'],['area','Area / GW'],['radar','Radar (percentiles)'],['histogram','Histogram'],['heatmap','2D density heatmap'],['box','Box plot'],['donut','Donut']];
const teamMetrics=[['xg','Expected goals'],['xga','Expected goals conceded'],['shots','Shots'],['shotsAgainst','Shots conceded'],['gf','Goals for'],['ga','Goals against'],['points','Points']];
const matchMetrics=[['xg','Total xG'],['shots','Total shots'],['goals','Total goals'],['xgDiff','Home - away xG'],['shotDiff','Home - away shots']];
function metricForSource(source,key){if(source==='players')return ms(key);if(source==='teams')return teamMetrics.find(([a])=>a===key)?.[1]||key;return matchMetrics.find(([a])=>a===key)?.[1]||key;}
function teamAggregate(id,weeks){const games=D.fixtures.filter(f=>weeks.has(+f.gw)&&(String(f.home)===String(id)||String(f.away)===String(id)));const sums={xg:0,xga:0,shots:0,shotsAgainst:0,gf:0,ga:0,points:0};for(const f of games){const h=String(f.home)===String(id);const gf=Number(h?f.homeScore:f.awayScore),ga=Number(h?f.awayScore:f.homeScore);sums.xg+=Number(h?f.xgHome:f.xgAway)||0;sums.xga+=Number(h?f.xgAway:f.xgHome)||0;sums.shots+=Number(h?f.shotsHome:f.shotsAway)||0;sums.shotsAgainst+=Number(h?f.shotsAway:f.shotsHome)||0;if(Number.isFinite(gf)&&Number.isFinite(ga)){sums.gf+=gf;sums.ga+=ga;sums.points+=gf>ga?3:gf===ga?1:0;}}return sums;}
function dataForChart(c){const weeks=c.gws,needsX=['scatter','bubble','heatmap'].includes(c.type);if(c.source==='players'){const pool=D.players.map(p=>({name:p.name,team:playerTeamForWeeks(p.id,weeks)||p.team,id:p.id,x:val(c.x,p.id,weeks),y:val(c.y,p.id,weeks),size:c.type==='bubble'?val(c.size||'m:total_shots',p.id,weeks):null,gws:weeks}));return pool.filter(d=>d.y!==null&&Number.isFinite(d.y)&&(!needsX||(d.x!==null&&Number.isFinite(d.x))));}if(c.source==='teams'){return D.teams.map(t=>{const sums=teamAggregate(t.id,weeks);return {name:t.name,team:t.id,id:t.id,x:sums[c.x],y:sums[c.y],size:c.type==='bubble'?sums[c.size]:null};});}return D.fixtures.filter(f=>weeks.has(+f.gw)).map(f=>{const sums={xg:Number(f.xgHome||0)+Number(f.xgAway||0),shots:Number(f.shotsHome||0)+Number(f.shotsAway||0),goals:Number(f.homeScore||0)+Number(f.awayScore||0),xgDiff:Number(f.xgHome||0)-Number(f.xgAway||0),shotDiff:Number(f.shotsHome||0)-Number(f.shotsAway||0)};return {name:tn(f.home)+' vs '+tn(f.away),team:f.home,id:f.id,x:sums[c.x],y:sums[c.y],size:c.type==='bubble'?sums[c.size]:null};});}
function defaultEntityId(source){if(source==='players')return String(D.players.slice().sort((a,b)=>(b.total||0)-(a.total||0))[0]?.id||'');if(source==='teams')return String(D.teams[0]?.id||'');return '';}
function ensureChartEntity(c){if(c.source==='players'&&!pmap.has(String(c.entityId)))c.entityId=defaultEntityId('players');if(c.source==='teams'&&!teams.has(String(c.entityId)))c.entityId=defaultEntityId('teams');if(c.source==='matches')c.entityId='';return c.entityId;}
function entityOptions(c){if(c.source==='players')return D.players.slice().sort((a,b)=>a.name.localeCompare(b.name)).map(p=>[String(p.id),p.name+' · '+tsh(playerTeamForWeeks(p.id,c.gws)||p.team)]);if(c.source==='teams')return D.teams.slice().sort((a,b)=>a.name.localeCompare(b.name)).map(t=>[String(t.id),t.name]);return [];}
const weeklyLogMap={
 'f:total_points':'points','f:event_points':'points','f:minutes':'minutes','f:goals_scored':'goals','f:assists':'assists','f:expected_goals':'xg','f:expected_assists':'xa','f:bonus':'bonus','f:defensive_contribution':'def','f:tackles':'tackles','f:recoveries':'recoveries'
};
function playerWeekValue(key,id,g){const field=weeklyLogMap[key];if(field){const row=(logsById.get(String(id))||[]).find(r=>+r.gw===+g);return row&&Number.isFinite(Number(row[field]))?Number(row[field]):null;}return val(key,id,new Set([+g]));}
function aggregateTimeline(c){ensureChartEntity(c);return getGwArray(c.gws).map(g=>{if(c.source==='players')return {g,v:playerWeekValue(c.y,c.entityId,g),label:pName(c.entityId),mode:weeklyLogMap[c.y]?'gameweek value':(mMap.get(c.y)?.mode==='snapshot'?'snapshot at GW':'gameweek aggregate')};if(c.source==='teams'){const sums=teamAggregate(c.entityId,new Set([g]));return {g,v:sums[c.y],label:tn(c.entityId),mode:'team gameweek value'};}const one={...c,gws:new Set([g])},data=dataForChart(one);return {g,v:data.reduce((a,b)=>a+(Number(b.y)||0),0),label:'League total',mode:'league total across matches'};});}
function markerSvg(c,d,x,y){const r=c.type==='bubble'?Math.min(14,4+Math.sqrt(Math.max(0,Number(d.size)||0))*1.35):4.3;const col=c.palette==='neutral'?'#c7cfc7':c.palette==='position'?positions[pmap.get(String(d.id))?.position]||'#8ba5a2':tc(d.team);const mark=c.marker||'dot';if(mark==='shirt')return `<path d="M-5 -6L-10 -2L-7 3L-5 2V9H5V2L7 3L10 -2L5 -6L2 -4H-2Z" transform="translate(${x} ${y}) scale(${Math.max(0.7,r/5.5)})" stroke="var(--bg)" stroke-width="1" fill="${col}"/>`;if(mark==='crest'&&teams.has(String(d.team)))return `<circle cx="${x}" cy="${y}" r="${r+2}" fill="${col}" opacity=".22"/><text x="${x}" y="${y+2.5}" fill="var(--text)" font-size="${Math.max(5,r*.8)}" text-anchor="middle" font-weight="800">${esc(tsh(d.team))}</text><image href="${logoUrl(d.team)}" x="${x-r-3}" y="${y-r-3}" width="${2*r+6}" height="${2*r+6}"/>`;if(mark==='photo'&&pmap.has(String(d.id))){const p=pmap.get(String(d.id));return `<circle cx="${x}" cy="${y}" r="${r+3}" fill="${col}"/><image href="assets/players/${encodeURIComponent(p.code||'missing')}.webp" x="${x-r-4}" y="${y-r-6}" width="${2*r+8}" height="${2*r+12}"/>`;}if(mark==='name')return `<text x="${x}" y="${y}" text-anchor="middle" font-size="8" fill="${col}">${esc(d.name.slice(0,13))}</text>`;return `<circle cx="${x}" cy="${y}" r="${r}" fill="${col}" opacity=".82" />`;}
function radarMetricKeys(source,c){if(source==='teams')return (c?.radarKeys||['xg','xga','shots','shotsAgainst','points']).filter(k=>teamMetrics.some(x=>x[0]===k));const keys=(c?.radarKeys||['m:xg','m:xa','m:total_shots','m:chances_created','m:touches_opposition_box']).filter(k=>mMap.has(k));return keys.slice(0,8);}
function radarValue(source,key,id,weeks){if(source==='players')return val(key,id,weeks);if(source==='teams')return teamAggregate(id,weeks)[key];return null;}
function radarPopulation(source,id,weeks){if(source==='teams')return D.teams.map(t=>t.id);const target=pmap.get(String(id)),pos=target?.position;return D.players.filter(p=>(!pos||p.position===pos)&&stats(p.id,weeks).minutes>0).map(p=>p.id);}
function percentile(source,key,id,weeks){const ids=radarPopulation(source,id,weeks),target=radarValue(source,key,id,weeks);if(target===null||!Number.isFinite(+target))return null;const vals=ids.map(x=>radarValue(source,key,x,weeks)).filter(v=>v!==null&&Number.isFinite(+v)).map(Number).sort((a,b)=>a-b);if(vals.length<2)return null;let below=0,equal=0;for(const v of vals){if(v<target)below++;else if(v===Number(target))equal++;}return {pct:100*(below+(equal-1)/2)/(vals.length-1),raw:Number(target),n:vals.length};}
