function chartThemeDecoration(c,W,H){if((c.theme||'club')!=='club')return '';const tid=chartSeriesTeam(c);if(!tid||!teams.has(String(tid)))return '';return `<g class="chart-club-watermark" opacity=".12"><image href="${esc(logoUrl(tid))}" x="${W-118}" y="18" width="88" height="88" preserveAspectRatio="xMidYMid meet"/><text x="${W-74}" y="120" text-anchor="middle" fill="var(--muted)" font-size="9" font-weight="700">${esc(tsh(tid))}</text></g>`;}
